-- ======================================================================== 04_views.sql
-- ReliefGrid: reporting and reconciliation views (MySQL 8.0)
-- Run after the tables exist (and after demo data if you want it loaded first; views do not depend on it).
USE reliefgrid;

DROP VIEW IF EXISTS v_inventory_available, v_open_demand, v_item_supply_demand, v_camp_overview, v_request_progress,
  v_ledger_mismatch, v_reservation_mismatch, v_allocation_mismatch, v_camp_stock_mismatch;

CREATE VIEW v_inventory_available AS
SELECT i.warehouse_id,
       w.name   AS warehouse_name,
       w.status AS warehouse_status,
       i.item_id,
       s.name   AS item_name,
       s.unit,
       c.name   AS category,
       i.quantity_on_hand,
       i.quantity_reserved,
       i.quantity_on_hand - i.quantity_reserved AS quantity_available,
       i.reorder_level,
       CASE WHEN i.reorder_level > 0 AND i.quantity_on_hand - i.quantity_reserved <= i.reorder_level THEN 1 ELSE 0 END AS below_reorder,
       i.updated_at
FROM inventory i
JOIN warehouses        w ON w.id = i.warehouse_id
JOIN supply_items      s ON s.id = i.item_id
JOIN supply_categories c ON c.id = s.category_id;

-- Request lines that still need stock (the allocator's work queue).
CREATE VIEW v_open_demand AS
SELECT ri.id                                      AS request_item_id,
       ri.request_id,
       r.camp_id,
       ri.item_id,
       r.urgency,
       r.created_at,
       ri.quantity_approved,
       ri.quantity_allocated,
       ri.quantity_approved - ri.quantity_allocated AS open_qty
FROM request_items ri
JOIN requests  r ON r.id = ri.request_id
JOIN camps     c ON c.id = r.camp_id
JOIN disasters d ON d.id = c.disaster_id
WHERE r.status IN ('PENDING','PARTIALLY_ALLOCATED')
  AND ri.quantity_allocated < ri.quantity_approved
  AND c.status <> 'CLOSED'
  AND d.status <> 'CLOSED';

-- Network-wide supply versus open demand per item: the basis of shortage alerts.
CREATE VIEW v_item_supply_demand AS
SELECT s.id        AS item_id,
       s.name      AS item_name,
       s.unit,
       cat.name    AS category,
       COALESCE(sup.available, 0)     AS available,
       COALESCE(dem.open_qty, 0)      AS open_demand,
       COALESCE(dem.open_requests, 0) AS open_lines,
       GREATEST(0, COALESCE(dem.open_qty, 0) - COALESCE(sup.available, 0)) AS shortage,
       CASE WHEN COALESCE(dem.open_qty, 0) > 0
            THEN ROUND(1.0 * LEAST(COALESCE(sup.available, 0), dem.open_qty) / dem.open_qty, 4)
            ELSE 1.0 END AS coverage
FROM supply_items s
JOIN supply_categories cat ON cat.id = s.category_id
LEFT JOIN (
  SELECT i.item_id, SUM(i.quantity_on_hand - i.quantity_reserved) AS available
  FROM inventory i JOIN warehouses w ON w.id = i.warehouse_id
  WHERE w.status = 'ACTIVE'
  GROUP BY i.item_id
) sup ON sup.item_id = s.id
LEFT JOIN (
  SELECT item_id, SUM(open_qty) AS open_qty, COUNT(*) AS open_requests
  FROM v_open_demand GROUP BY item_id
) dem ON dem.item_id = s.id
WHERE s.active = 1;

CREATE VIEW v_camp_overview AS
SELECT c.id AS camp_id,
       c.name, c.district, c.status, c.latitude, c.longitude,
       c.population, c.vulnerable_count, c.capacity, c.disaster_id,
       (SELECT COUNT(*) FROM requests r
         WHERE r.camp_id = c.id AND r.status IN ('PENDING','PARTIALLY_ALLOCATED')) AS open_requests,
       (SELECT COALESCE(MAX(r.urgency), 0) FROM requests r
         WHERE r.camp_id = c.id AND r.status IN ('PENDING','PARTIALLY_ALLOCATED')) AS max_open_urgency,
       (SELECT COUNT(*) FROM shipments s
         WHERE s.camp_id = c.id AND s.status IN ('PLANNED','IN_TRANSIT')) AS active_shipments,
       (SELECT COALESCE(SUM(d.people_served), 0) FROM distributions d WHERE d.camp_id = c.id) AS people_served_total
FROM camps c;

CREATE VIEW v_request_progress AS
SELECT r.id AS request_id, r.camp_id, r.status, r.urgency, r.created_at,
       COUNT(ri.id)                                                                   AS lines_total,
       SUM(CASE WHEN ri.quantity_allocated >= ri.quantity_approved THEN 1 ELSE 0 END) AS lines_allocated,
       SUM(CASE WHEN ri.quantity_delivered >= ri.quantity_approved THEN 1 ELSE 0 END) AS lines_delivered
FROM requests r
JOIN request_items ri ON ri.request_id = r.id
GROUP BY r.id, r.camp_id, r.status, r.urgency, r.created_at;

-- ---------------------------------------------------------------------------------------------
-- Reconciliation views: each should return zero rows when the data is consistent.
-- (MySQL cannot filter on a SELECT alias in WHERE, so each is wrapped in a derived table.)
-- ---------------------------------------------------------------------------------------------
-- inventory must equal the replayed ledger
CREATE VIEW v_ledger_mismatch AS
SELECT x.warehouse_id, x.item_id, x.quantity_on_hand, x.quantity_reserved, x.ledger_on_hand, x.ledger_reserved
FROM (
  SELECT i.warehouse_id, i.item_id, i.quantity_on_hand, i.quantity_reserved,
         COALESCE(SUM(m.delta_on_hand), 0)  AS ledger_on_hand,
         COALESCE(SUM(m.delta_reserved), 0) AS ledger_reserved
  FROM inventory i
  LEFT JOIN stock_movements m ON m.warehouse_id = i.warehouse_id AND m.item_id = i.item_id
  GROUP BY i.warehouse_id, i.item_id, i.quantity_on_hand, i.quantity_reserved
) x
WHERE x.quantity_on_hand <> x.ledger_on_hand OR x.quantity_reserved <> x.ledger_reserved;

-- reserved stock must equal the quantity on PLANNED shipments
CREATE VIEW v_reservation_mismatch AS
SELECT x.warehouse_id, x.item_id, x.quantity_reserved, x.planned_qty
FROM (
  SELECT i.warehouse_id, i.item_id, i.quantity_reserved,
         COALESCE((SELECT SUM(si.quantity)
                   FROM shipment_items si JOIN shipments sh ON sh.id = si.shipment_id
                   WHERE sh.warehouse_id = i.warehouse_id AND si.item_id = i.item_id AND sh.status = 'PLANNED'), 0) AS planned_qty
  FROM inventory i
) x
WHERE x.quantity_reserved <> x.planned_qty;

-- allocated/delivered counters on request lines must equal what the shipments say
CREATE VIEW v_allocation_mismatch AS
SELECT x.request_item_id, x.quantity_allocated, x.quantity_delivered, x.shipment_qty, x.received_qty
FROM (
  SELECT ri.id AS request_item_id, ri.quantity_allocated, ri.quantity_delivered,
         COALESCE((SELECT SUM(CASE sh.status WHEN 'DELIVERED' THEN si.quantity_received ELSE si.quantity END)
                   FROM shipment_items si JOIN shipments sh ON sh.id = si.shipment_id
                   WHERE si.request_item_id = ri.id AND sh.status <> 'CANCELLED'), 0) AS shipment_qty,
         COALESCE((SELECT SUM(si.quantity_received)
                   FROM shipment_items si JOIN shipments sh ON sh.id = si.shipment_id
                   WHERE si.request_item_id = ri.id AND sh.status = 'DELIVERED'), 0) AS received_qty
  FROM request_items ri
) x
WHERE x.quantity_allocated <> x.shipment_qty OR x.quantity_delivered <> x.received_qty;

-- camp stock must equal deliveries minus distributions
CREATE VIEW v_camp_stock_mismatch AS
SELECT x.camp_id, x.item_id, x.quantity, x.expected
FROM (
  SELECT cs.camp_id, cs.item_id, cs.quantity,
         COALESCE((SELECT SUM(si.quantity_received)
                   FROM shipment_items si JOIN shipments sh ON sh.id = si.shipment_id
                   WHERE sh.camp_id = cs.camp_id AND si.item_id = cs.item_id AND sh.status = 'DELIVERED'), 0)
       - COALESCE((SELECT SUM(d.quantity) FROM distributions d
                   WHERE d.camp_id = cs.camp_id AND d.item_id = cs.item_id), 0) AS expected
  FROM camp_stock cs
) x
WHERE x.quantity <> x.expected;

-- ======================================================================== 05_triggers.sql
-- ReliefGrid: integrity enforced inside the database (21 triggers, MySQL 8.0 SIGNAL syntax)
-- Load the demo data (03_demo_data.sql) BEFORE creating these triggers: otherwise the shipment triggers would
-- write a second, duplicate timeline row for every shipment inserted by the bulk load.
-- In MySQL Workbench the DELIMITER lines below are understood by the script runner.
USE reliefgrid;

DROP TRIGGER IF EXISTS trg_stock_movements_no_update;
DROP TRIGGER IF EXISTS trg_stock_movements_no_delete;
DROP TRIGGER IF EXISTS trg_allocation_runs_no_update;
DROP TRIGGER IF EXISTS trg_allocation_runs_no_delete;
DROP TRIGGER IF EXISTS trg_allocation_decisions_no_update;
DROP TRIGGER IF EXISTS trg_allocation_decisions_no_delete;
DROP TRIGGER IF EXISTS trg_allocation_lines_no_update;
DROP TRIGGER IF EXISTS trg_allocation_lines_no_delete;
DROP TRIGGER IF EXISTS trg_shipment_events_no_update;
DROP TRIGGER IF EXISTS trg_shipment_events_no_delete;
DROP TRIGGER IF EXISTS trg_audit_log_no_update;
DROP TRIGGER IF EXISTS trg_audit_log_no_delete;
DROP TRIGGER IF EXISTS trg_shipments_valid_transition;
DROP TRIGGER IF EXISTS trg_shipments_event_on_insert;
DROP TRIGGER IF EXISTS trg_shipments_event_on_status;
DROP TRIGGER IF EXISTS trg_shipment_items_immutable;
DROP TRIGGER IF EXISTS trg_shipment_items_receipt_state;
DROP TRIGGER IF EXISTS trg_requests_camp_open;
DROP TRIGGER IF EXISTS trg_requests_urgency_no_downgrade_when_closed;
DROP TRIGGER IF EXISTS trg_inventory_no_delete_with_stock;
DROP TRIGGER IF EXISTS trg_distribution_stock_guard;

-- ---------------------------------------------------------------------------------------------
-- Append-only history tables (single-statement triggers need no DELIMITER)
-- ---------------------------------------------------------------------------------------------
CREATE TRIGGER trg_stock_movements_no_update BEFORE UPDATE ON stock_movements FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'stock_movements is append-only';
CREATE TRIGGER trg_stock_movements_no_delete BEFORE DELETE ON stock_movements FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'stock_movements is append-only';

CREATE TRIGGER trg_allocation_runs_no_update BEFORE UPDATE ON allocation_runs FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';
CREATE TRIGGER trg_allocation_runs_no_delete BEFORE DELETE ON allocation_runs FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';
CREATE TRIGGER trg_allocation_decisions_no_update BEFORE UPDATE ON allocation_decisions FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';
CREATE TRIGGER trg_allocation_decisions_no_delete BEFORE DELETE ON allocation_decisions FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';
CREATE TRIGGER trg_allocation_lines_no_update BEFORE UPDATE ON allocation_lines FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';
CREATE TRIGGER trg_allocation_lines_no_delete BEFORE DELETE ON allocation_lines FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'allocation history is immutable';

CREATE TRIGGER trg_shipment_events_no_update BEFORE UPDATE ON shipment_events FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'shipment_events is append-only';
CREATE TRIGGER trg_shipment_events_no_delete BEFORE DELETE ON shipment_events FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'shipment_events is append-only';

CREATE TRIGGER trg_audit_log_no_update BEFORE UPDATE ON audit_log FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_log is append-only';
CREATE TRIGGER trg_audit_log_no_delete BEFORE DELETE ON audit_log FOR EACH ROW
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_log is append-only';

-- ---------------------------------------------------------------------------------------------
-- Shipments: state machine + automatic event log, shipment-line rules
-- ---------------------------------------------------------------------------------------------
DELIMITER $$

CREATE TRIGGER trg_shipments_valid_transition BEFORE UPDATE ON shipments FOR EACH ROW
BEGIN
  IF OLD.status <> NEW.status AND NOT (
       (OLD.status = 'PLANNED'    AND NEW.status IN ('IN_TRANSIT', 'CANCELLED')) OR
       (OLD.status = 'IN_TRANSIT' AND NEW.status = 'DELIVERED')) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'invalid shipment status transition';
  END IF;
END$$

CREATE TRIGGER trg_shipments_event_on_insert AFTER INSERT ON shipments FOR EACH ROW
BEGIN
  INSERT INTO shipment_events (shipment_id, status, actor_id, note, created_at)
  VALUES (NEW.id, NEW.status, NEW.last_actor_id, NEW.last_note, NEW.status_changed_at);
END$$

CREATE TRIGGER trg_shipments_event_on_status AFTER UPDATE ON shipments FOR EACH ROW
BEGIN
  IF OLD.status <> NEW.status THEN
    INSERT INTO shipment_events (shipment_id, status, actor_id, note, created_at)
    VALUES (NEW.id, NEW.status, NEW.last_actor_id, NEW.last_note, NEW.status_changed_at);
  END IF;
END$$

-- Lines of a shipment are fixed once created; only the receipt count may be recorded.
CREATE TRIGGER trg_shipment_items_immutable BEFORE UPDATE ON shipment_items FOR EACH ROW
BEGIN
  IF NOT (NEW.shipment_id <=> OLD.shipment_id AND NEW.request_item_id <=> OLD.request_item_id
          AND NEW.item_id <=> OLD.item_id AND NEW.quantity <=> OLD.quantity) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'shipment lines are immutable';
  END IF;
END$$

-- Receipts may only be recorded for shipments that are in transit.
CREATE TRIGGER trg_shipment_items_receipt_state BEFORE UPDATE ON shipment_items FOR EACH ROW
BEGIN
  IF NOT (NEW.quantity_received <=> OLD.quantity_received)
     AND (SELECT status FROM shipments WHERE id = NEW.shipment_id) <> 'IN_TRANSIT' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'receipts can only be recorded for in-transit shipments';
  END IF;
END$$

-- ---------------------------------------------------------------------------------------------
-- Business rules
-- ---------------------------------------------------------------------------------------------
CREATE TRIGGER trg_requests_camp_open BEFORE INSERT ON requests FOR EACH ROW
BEGIN
  IF (SELECT status FROM camps WHERE id = NEW.camp_id) = 'CLOSED' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cannot create requests for a closed camp';
  END IF;
END$$

CREATE TRIGGER trg_requests_urgency_no_downgrade_when_closed BEFORE UPDATE ON requests FOR EACH ROW
BEGIN
  IF OLD.status IN ('FULFILLED', 'CANCELLED') AND NEW.urgency <> OLD.urgency THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cannot change urgency of a closed request';
  END IF;
END$$

CREATE TRIGGER trg_inventory_no_delete_with_stock BEFORE DELETE ON inventory FOR EACH ROW
BEGIN
  IF OLD.quantity_on_hand > 0 OR OLD.quantity_reserved > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'cannot delete an inventory row that still holds stock';
  END IF;
END$$

CREATE TRIGGER trg_distribution_stock_guard BEFORE INSERT ON distributions FOR EACH ROW
BEGIN
  IF COALESCE((SELECT quantity FROM camp_stock WHERE camp_id = NEW.camp_id AND item_id = NEW.item_id), 0) < NEW.quantity THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'distribution exceeds stock held at the camp';
  END IF;
END$$

DELIMITER ;

